// The `hoocode --help` text. Written by hand: list only what this build does. A flag
// that parses but is not implemented (see `unsupported_flags` in lib.rs) stays out of
// it, and so does any command that is not wired. Tests: `help.rs`.

use crate::help::Seg;

pub(crate) const HELP_SEGMENTS: &[Seg] = &[
    Seg::Bold("hoocode"),
    Seg::Plain(" - AI coding agent with Read, Shell, Edit, Write and CodeSearch tools\n\n"),
    Seg::Bold("Usage:"),
    Seg::Plain("\n  hoocode [options] [@files...] [messages...]\n\n"),
    Seg::Bold("Commands:"),
    Seg::Plain("\n  hoocode install <name[@marketplace]> [--scope user|project]\n                                    Install a plugin from a marketplace\n  hoocode remove <name> [--scope user|project]\n                                    Remove an installed plugin (alias: uninstall)\n  hoocode list                      List plugin marketplaces and installed plugins\n  hoocode plugin <command>          Every plugin command (marketplaces, update, trust);\n                                    inside a session it is /plugin\n  hoocode config                    Open a TUI to turn skills, prompts and other resources on or off\n  hoocode update                    Print the command that updates hoocode\n  hoocode migrate [--dry-run]       Merge data from an older hoocode home folder into ~/.hoocode\n  hoocode app-server [--listen URL] Serve this folder's sessions over the app-server protocol\n  hoocode <command> --help          Show help for install, remove, list, plugin and app-server\n\n"),
    Seg::Bold("Options:"),
    Seg::Plain("\n  --provider <name>              Provider name (default: the first one with a key or login)\n  --model <pattern>              Model pattern or ID (supports \"provider/id\" and optional \":<thinking>\")\n  --api-key <key>                API key (defaults to env vars)\n  --system-prompt <text>         System prompt (default: coding assistant prompt)\n  --mode <mode>                  Output mode: text (default), json, or rpc\n  --print, -p                    Non-interactive mode: process prompt and exit\n  --continue, -c                 Continue previous session\n  --resume, -r                   Select a session to resume\n  --session <path|id>            Use specific session file or partial UUID\n  --fork <path|id>               Fork specific session file or partial UUID into a new session\n  --session-dir <dir>            Directory for session storage and lookup\n  --no-session                   Don't save session (ephemeral)\n  --perf-log <file>              Append one JSON line of UI performance counters (threads, RSS,\n                                 frame and keystroke timing, stalls) to <file> every second\n  --models <patterns>            Comma-separated model patterns for Ctrl+P cycling\n                                 Supports globs (anthropic/*, *sonnet*) and fuzzy matching\n  --no-tools, -nt                Disable all tools by default\n  --no-builtin-tools, -nbt       Disable built-in tools by default but keep MCP and plugin tools\n  --tools, -t <tools>            Comma-separated allowlist of tool names to enable\n  --disallowed-tools <tools>     Comma-separated denylist of tool names to disable\n                                 (subtracted from the allowlist or default set)\n  --max-turns <n>                Hard cap on assistant turns; the agent is asked to wrap up near the\n                                 cap and stopped at it (mainly used for spawned subagents)\n  --enable-subagents             Enable the subagent tool (delegate tasks to isolated agent loops).\n                                 On by default (the \"enableSubagent\" setting defaults to true)\n  --no-subagents                 Disable the subagent tool for this session (overrides the setting)\n  --warm-subagents               Dispatch eligible subagents on reused warm RPC workers (experimental)\n  --max-subagent-depth <n>       Tree-wide subagent nesting cap (default 4 = three levels of nesting;\n                                 1 = no nesting). Overrides the \"maxSubagentDepth\" setting\n  --enable-plugintools           Let the agent search, install and write plugins (off by default)\n                                  Plugin lifecycle tools (SearchPlugins, InstallPlugin, ...) and\n                                  ProposePlugin, plus the runtime plugin-reuse nudge\n                                  Can also be enabled via the \"enablePluginTools\" setting,\n                                  which /settings -> Plugins -> Plugin system writes\n  --light                        Minimal low-token preset for small/local models:\n                                  only the Read/Write/Edit/Shell tools (short descriptions,\n                                  stripped schemas; search via Shell), a terse system prompt, and\n                                  no subagents/TodoWrite/skills/context files/mode appendix\n                                  Can also be enabled via the \"light\" setting\n  --thinking <level>             Set thinking level: off, minimal, low, medium, high, xhigh\n  --skill <path>                 Load a skill file or directory (can be used multiple times)\n  --no-skills, -ns               Disable skills discovery and loading\n  --prompt-template <path>       Load a prompt template / slash command file or directory (repeatable)\n  --slash-command <path>         Alias of --prompt-template (prompts and slash commands are one feature)\n  --no-prompt-templates, -np     Disable prompt template / slash command discovery (same as --no-slash-commands)\n  --no-slash-commands, -nsc      Disable prompt template / slash command discovery (same as --no-prompt-templates)\n  --mode-path <dir>              Add a directory to search for {name}/system.md mode files (can be used multiple times)\n  --no-context-files, -nc        Disable AGENTS.md and CLAUDE.md discovery and loading\n  --list-models [search]         List available models (with optional fuzzy search)\n  --offline                      Disable startup network operations (same as HOOCODE_OFFLINE=1)\n  --ca-cert <path>               Trust an extra PEM CA bundle for hoocode's own TLS traffic (provider\n                                 calls, GitHub API, downloads). Additive to the bundled roots;\n                                 verification stays ON. Also: HOOCODE_CA_CERT / NODE_EXTRA_CA_CERTS.\n  --use-system-ca                Also trust the OS/system CA store (opt-in). Same as\n                                 HOOCODE_USE_SYSTEM_CA=1\n  --help, -h                     Show this help\n  --version, -v                  Show version number"),
    Seg::Ext,
    Seg::Plain("\n\n"),
    Seg::Bold("Examples:"),
    Seg::Plain("\n  # Interactive mode\n  hoocode\n\n  # Interactive mode with initial prompt\n  hoocode \"List the Rust files in src/\"\n\n  # Include files in initial message\n  hoocode @prompt.md @image.png \"What color is the sky?\"\n\n  # Non-interactive mode (process and exit)\n  hoocode -p \"List the Rust files in src/\"\n\n  # Multiple messages (interactive)\n  hoocode \"Read Cargo.toml\" \"What dependencies do we have?\"\n\n  # Continue previous session\n  hoocode --continue \"What did we discuss?\"\n\n  # Use different model\n  hoocode --provider openai --model gpt-4o-mini \"Help me refactor this code\"\n\n  # Use model with provider prefix (no --provider needed)\n  hoocode --model openai/gpt-4o \"Help me refactor this code\"\n\n  # Use model with thinking level shorthand\n  hoocode --model sonnet:high \"Solve this complex problem\"\n\n  # Limit model cycling to specific models\n  hoocode --models claude-sonnet,claude-haiku,gpt-4o\n\n  # Limit to a specific provider with glob pattern\n  hoocode --models \"github-copilot/*\"\n\n  # Cycle models with fixed thinking levels\n  hoocode --models sonnet:high,haiku:low\n\n  # Start with a specific thinking level\n  hoocode --thinking high \"Solve this complex problem\"\n\n  # Read-only mode (no file modifications possible)\n  hoocode --tools Read,CodeSearch -p \"Review the code in src/\"\n\n  # Install a plugin from a marketplace added with `hoocode plugin marketplace add`\n  hoocode install <plugin>@<marketplace>\n\n"),
    Seg::Bold("Environment Variables:"),
    Seg::Plain("\n  ANTHROPIC_API_KEY                - Anthropic Claude API key\n  ANTHROPIC_OAUTH_TOKEN            - Anthropic OAuth token (alternative to API key)\n  OPENAI_API_KEY                   - OpenAI GPT API key\n  DEEPSEEK_API_KEY                 - DeepSeek API key\n  GEMINI_API_KEY                   - Google Gemini API key\n  GOOGLE_CLOUD_PROJECT             - Cloud project for Code Assist logins (paid/Workspace accounts)\n  HOOCODE_ANTIGRAVITY_CLIENT_ID    - OAuth client id for the Google Antigravity login\n  HOOCODE_ANTIGRAVITY_CLIENT_SECRET - OAuth client secret for the Google Antigravity login\n  HOOCODE_GEMINI_CLI_CLIENT_ID     - OAuth client id for the Gemini CLI login\n  HOOCODE_GEMINI_CLI_CLIENT_SECRET - OAuth client secret for the Gemini CLI login\n  GROQ_API_KEY                     - Groq API key\n  CEREBRAS_API_KEY                 - Cerebras API key\n  XAI_API_KEY                      - xAI Grok API key\n  FIREWORKS_API_KEY                - Fireworks API key\n  TOGETHER_API_KEY                 - Together AI API key\n  OPENROUTER_API_KEY               - OpenRouter API key\n  AI_GATEWAY_API_KEY               - Vercel AI Gateway API key\n  HF_TOKEN                         - Hugging Face token\n  ZAI_API_KEY                      - ZAI API key\n  MINIMAX_API_KEY                  - MiniMax API key\n  MOONSHOT_API_KEY                 - Moonshot AI API key\n  OPENCODE_API_KEY                 - OpenCode Zen/OpenCode Go API key\n  KIMI_API_KEY                     - Kimi For Coding API key\n  XIAOMI_API_KEY                   - Xiaomi MiMo API key (api.xiaomimimo.com billing)\n  XIAOMI_TOKEN_PLAN_CN_API_KEY     - Xiaomi MiMo Token Plan API key (China region)\n  XIAOMI_TOKEN_PLAN_AMS_API_KEY    - Xiaomi MiMo Token Plan API key (Amsterdam region)\n  XIAOMI_TOKEN_PLAN_SGP_API_KEY    - Xiaomi MiMo Token Plan API key (Singapore region)\n  NVIDIA_API_KEY                   - NVIDIA API key (integrate.api.nvidia.com)\n  HOOCODE_CODING_AGENT_DIR         - Config directory (default: ~/.hoocode)\n  HOOCODE_CODING_AGENT_SESSION_DIR - Session storage directory (overridden by --session-dir)\n  HOOCODE_USER_AGENTS_DIR          - Folder for user plugins and mcp.json (default: ~/.agents)\n  HOOCODE_PACKAGE_DIR              - Folder of hoocode's bundled files such as CHANGELOG.md\n                                     (for Nix/Guix store paths)\n  HOOCODE_OFFLINE                  - Disable startup network operations when set to 1/true/yes.\n  HOOCODE_FULLSCREEN               - Set to 0 to run the interactive screen inline instead of full-screen\n  HOOCODE_CA_CERT                  - Path to an extra PEM CA bundle to trust for hoocode's own TLS traffic\n                                     (additive; verification stays on). Precedence: --ca-cert > this > NODE_EXTRA_CA_CERTS\n  HOOCODE_USE_SYSTEM_CA            - Also trust the OS/system CA store when set to 1/true/yes (same as --use-system-ca)\n  NODE_EXTRA_CA_CERTS              - Path to an extra PEM CA bundle (the lowest-precedence CA source)\n  HOOCODE_TELEMETRY                - Set to 1/true/yes or 0/false/no to override the \"enableInstallTelemetry\"\n                                     setting (OpenRouter app attribution headers)\n\n"),
    Seg::Bold("Built-in Tool Names:"),
    Seg::Plain("\n  Read       - Read file contents\n  Shell      - Execute shell commands\n  Edit       - Edit files with find/replace\n  Write      - Write files (creates/overwrites)\n  CodeSearch - Ranked code search (read-only)\n"),
];
